<template>
    <div>
        <div class="app-content content">
            <div class="content-wrapper">
                <div class="content-header row">
                    <div class="content-header-left col-12 mb-1 mt-0">
                        <div class="row breadcrumbs-top">
                            <div class="col-12">
                                <div class="breadcrumb-wrapper col-12">
                                    <ol class="breadcrumb p-0 mb-0">
                                        <li class="breadcrumb-item"><router-link :to="{ path: '/' }"><i
                                                    class="bx bx-home-alt"></i></router-link>
                                        </li>
                                        <li class="breadcrumb-item  "> <router-link :to="{ path: '/projects' }"> Priority
                                                Task </router-link>
                                        </li>
                                        <li class="breadcrumb-item active"> Priority Task
                                        </li>

                                    </ol>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="content-body">
                    <section class="input-validation">
                        <div class="row">
                            <div class="col-md-12">
                                <div class="card">
                                    <div class="card-header">
                                        <h4 class="card-title">Update Priority Task</h4>
                                    </div>
                                    <div class="card-content">
                                        <div class="card-body">
                                            <form @submit.prevent="update()">
                                                <!-- <div class="row">
                                                    <div class="col-md-3">

                                                        <div class="form-group">
                                                            <label for="Profession">Quarter </label>
                                                            <div class="controls">
                                                                <select class="form-control" v-model="addForm.quarter"
                                                                    id="users-list-verified">
                                                                    <option value="">Select One</option>
                                                                    <option v-for="row in quarter_months" :key="row.id"
                                                                        :value="row.id">
                                                                        {{ row.name }}
                                                                    </option>
                                                                </select>
                                                            </div>
                                                        </div>

                                                    </div>
                                                </div> -->

                                                <div class="row">
                                                    <div class="col-12">
                                                        <div class="card">

                                                            <div class="card-content">
                                                                <div class="card-body card-dashboard">
                                                                    <br><br>
                                                                    <table class="table table-bordered table-sm">
                                                                        <thead class="thead-dark">
                                                                            <tr>
                                                                                <th style="width: 100px;">Priority</th>
                                                                                <th style="width: 30%;">Major Task </th>
                                                                                <th style="">October
                                                                                    ({{ sumWeightage('oct') }}%)</th>
                                                                                <th style="">November
                                                                                    ({{ sumWeightage('nov') }}%)</th>
                                                                                <th style="">December
                                                                                    ({{ sumWeightage('dec') }}%)</th>
                                                                                <th style="">Qtr-2
                                                                                    ({{ sumWeightage('quarter_weightage')
                                                                                    }}%)
                                                                                </th>
                                                                                <th style="">Half Year
                                                                                    Weightage({{
                                                                                        sumWeightage('half_year_weightage') }}%)
                                                                                </th>
                                                                                <th style="">Year
                                                                                    Weightage({{
                                                                                        sumWeightage('year_weightage') }}%)
                                                                                </th>
                                                                                <th style="">Achievement (%)</th>
                                                                                <th style="">Action</th>

                                                                            </tr>
                                                                        </thead>
                                                                        <tbody>
                                                                            <template
                                                                                v-for="(schedule, index) in addForm.tasks">
                                                                                <tr :key="index">
                                                                                    <td>Priority {{ index + 1 }}</td>
                                                                                    <td>
                                                                                        <div class="form-group">
                                                                                            <div class="controls">

                                                                                                <textarea rows="1"
                                                                                                    v-model="addForm.tasks[index].task"
                                                                                                    class="form-control "
                                                                                                    placeholder="Task "></textarea>

                                                                                            </div>
                                                                                        </div>
                                                                                    </td>

                                                                                    <td>
                                                                                        <div class="form-group">
                                                                                            <div class="controls">
                                                                                                <input type="text"
                                                                                                    name="name"
                                                                                                    v-model="addForm.tasks[index].oct"
                                                                                                    :class="{ 'is-invalid': addForm.errors.has('name'), }"
                                                                                                    class="form-control"
                                                                                                    @keyup="handleKeyUp($event, index, 'oct')"
                                                                                                    data-validation-required-message="This
                                                                                                field is required"
                                                                                                    placeholder="Weightage (%)">
                                                                                            </div>
                                                                                        </div>
                                                                                    </td>
                                                                                    <td>
                                                                                        <div class="form-group">
                                                                                            <div class="controls">
                                                                                                <input type="text"
                                                                                                    name="name"
                                                                                                    v-model="addForm.tasks[index].nov"
                                                                                                    :class="{ 'is-invalid': addForm.errors.has('name'), }"
                                                                                                    class="form-control"
                                                                                                    @keyup="handleKeyUp($event, index, 'nov')"
                                                                                                    data-validation-required-message="This field is required"
                                                                                                    placeholder="Weightage (%)">
                                                                                            </div>
                                                                                        </div>
                                                                                    </td>
                                                                                    <td>
                                                                                        <div class="form-group">
                                                                                            <div class="controls">
                                                                                                <input type="text"
                                                                                                    name="name"
                                                                                                    v-model="addForm.tasks[index].dec"
                                                                                                    :class="{ 'is-invalid': addForm.errors.has('name'), }"
                                                                                                    class="form-control"
                                                                                                    @keyup="handleKeyUp($event, index, 'dec')"
                                                                                                    data-validation-required-message="This field is required"
                                                                                                    placeholder="Weightage (%)">
                                                                                            </div>
                                                                                        </div>
                                                                                    </td>
                                                                                    <td>
                                                                                        <div class="form-group">
                                                                                            <div class="controls">
                                                                                                <input type="text"
                                                                                                    name="name"
                                                                                                    v-model="addForm.tasks[index].quarter_weightage"
                                                                                                    :class="{ 'is-invalid': addForm.errors.has('name'), }"
                                                                                                    class="form-control"
                                                                                                    @keyup="handleKeyUp($event, index, 'quarter_weightage')"
                                                                                                    data-validation-required-message="This field is required"
                                                                                                    placeholder="Weightage (%)">
                                                                                            </div>
                                                                                        </div>
                                                                                    </td>
                                                                                    <td>
                                                                                        <div class="form-group">
                                                                                            <div class="controls">
                                                                                                <input type="text"
                                                                                                    name="half_year_weightage"
                                                                                                    max="100"
                                                                                                    v-model="addForm.tasks[index].half_year_weightage"
                                                                                                    :class="{ 'is-invalid': addForm.errors.has('half_year_weightage'), }"
                                                                                                    class="form-control"
                                                                                                    @keyup="handleKeyUp($event, index, 'half_year_weightage')"
                                                                                                    data-validation-required-message="This field is required"
                                                                                                    placeholder="Half Year Weightage (%)">
                                                                                            </div>
                                                                                        </div>
                                                                                    </td>

                                                                                    <td>
                                                                                        <div class="form-group">
                                                                                            <div class="controls">
                                                                                                <input type="text"
                                                                                                    name="namyear_weightagee"
                                                                                                    v-model="addForm.tasks[index].year_weightage"
                                                                                                    @keyup="handleKeyUp($event, index, 'year_weightage')"
                                                                                                    :class="{ 'is-invalid': addForm.errors.has('name'), }"
                                                                                                    class="form-control"
                                                                                                    data-validation-required-message="This field is required"
                                                                                                    placeholder="Yeary Weightage (%)">
                                                                                            </div>
                                                                                        </div>
                                                                                    </td>
                                                                                    <td>

                                                                                        <div class="form-group">
                                                                                            <div class="controls">
                                                                                                <input type="text"
                                                                                                    name="name"
                                                                                                    v-model="addForm.tasks[index].quarter_achiv"
                                                                                                    :class="{ 'is-invalid': addForm.errors.has('name'), }"
                                                                                                    class="form-control"
                                                                                                    @keyup="handleKeyUpAchive($event, index)"
                                                                                                    data-validation-required-message="This field is required"
                                                                                                    placeholder="Weightage (%)">
                                                                                            </div>
                                                                                        </div>


                                                                                    </td>
                                                                                    <td>

                                                                                        <button class="btn-danger"
                                                                                            type="button"
                                                                                            @click="item_removes(index)"><i
                                                                                                class="bx bx-trash"></i></button>
                                                                                        <button class="btn-success"
                                                                                            type="button" @click="AddMore()"
                                                                                            v-if="(addForm.tasks.length - 1 == index)"><i
                                                                                                class="bx bx-plus"></i></button>
                                                                                    </td>
                                                                                </tr>
                                                                            </template>

                                                                        </tbody>
                                                                    </table>
                                                                    <div style="position: relative;">
                                                                        <div style="position: absolute; right: 0px;">

                                                                            <button type="submit"
                                                                                class="btn btn-primary">Update</button>
                                                                        </div>
                                                                    </div>



                                                                </div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>

                                            </form>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </section>
                    <!-- Input Validation end -->
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import axios from "../../axios_instance";
import { Form } from "vform";
export default {
    props: {
    },
    components: {
        // VueRecaptcha, facebookLogin 
    },
    data() {
        return {
            base_url: window.base_url,
            api_url: window.api_url,
            DepartmentsItems: [],
            token: this.$localStorage.get("d_token"),
            addForm: new Form({
                tasks: [],
                quarter: 2,
                id: 0

            }),
            roles: [],
        };
    },
    created() {
        this.getItems();
    },
    methods: {

        sumWeightage(month) {
            const sum = this.addForm.tasks.reduce((accumulator, task) => {
                return accumulator + Number(task[month]);
            }, 0);
            return sum;
        },
        AddMore() {

            this.addForm.tasks.push(
                {
                    id: 0,
                    task: "",
                    quarter_weightage: "",
                    jan: "",
                    feb: "",
                    mar: "",
                    apr: "",
                    may: "",
                    jun: "",
                    jul: "",
                    aug: "",
                    sep: "",
                    oct: "",
                    nov: "",
                    dec: "",
                    quarter_achiv: "",
                    half_year_weightage: "",
                    year_weightage: "",
                    priority_value: 5,
                }
            )
        },
        item_removes(id) {
            console.log(id);
            this.$swal({
                title: "Are you sure?",
                text: "Once deleted, you will not be able to recover this item!",
                icon: "warning",
                buttons: true,
                dangerMode: true,
            })
                .then((willDelete) => {
                    if (willDelete) {
                        if(this.addForm.tasks[id].id){
                            this.delete_row(this.addForm.tasks[id].id)
                        } 
                        this.addForm.tasks.splice(id, 1);
                        
                    }
                });
        },
        handleKeyUpAchive(event, index){ 
            const value = this.addForm.tasks[index]['quarter_achiv']; 
            const numericValue = parseFloat(value.replace(/[^\d.]/g, 0));
            this.addForm.tasks[index]['quarter_achiv'] =  numericValue;
            if(numericValue > 100){
                this.addForm.tasks[index]['quarter_achiv'] =  100;
            }
        },
        handleKeyUp(event, index, month) {
            const value = this.addForm.tasks[index][month]; 
            const numericValue = parseFloat(value.replace(/[^\d.]/g, 0));
            this.addForm.tasks[index][month] =  numericValue;

            const sum = this.addForm.tasks.reduce((accumulator, task) => {
                return accumulator + Number(task[month]);
            }, 0);
            if (100 <= sum) {
                const diff = sum - 100;

                if (diff > 0) {
                    // If the difference is positive, reduce the current value by the difference
                    this.addForm.tasks[index][month] -= diff;
                }
                this.$toasted.show('The maximum weightage is 100.', {
                    theme: "bubble",
                    duration: 2000,
                    position: "bottom-right",
                });
            }
        },
        async getItems() {
            let loader = this.$loading.show();
            try {
                await axios
                    .get(this.api_url + "priority_tasks/" + this.$route.params.id, {
                        headers: {
                            "Content-Type": "application/json",
                            Authorization: this.token ? `Bearer ${this.token}` : ""
                        },
                    })
                    .then(({
                        data
                    }) => {
                        this.addForm.tasks = data.data.tasks;
                        this.addForm.quarter = data.data.quarter;
                        this.addForm.id = data.data.id;
                        loader.hide();
                    });
            } catch (error) {
                loader.hide();
            }
        },
        async update() {
            try {
                let loader = this.$loading.show();
                this.addForm.post(this.api_url + "priority_task_items_update?id=" + this.$route.params.id, {
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: this.token ? `Bearer ${this.token}` : ""
                    },
                }).then((res) => {
                    console.log(res);
                    if (res.data.success) {
                        this.$toasted.show(res.data.message, {
                            theme: "bubble",
                            duration: 5000,
                            position: "bottom-right",
                        });
                    }
                    loader.hide();
                    //  this.$router.push('/users');
                }, (error) => {
                    console.log(error);
                    loader.hide();
                })
            } catch (error) {
                // loader.hide(); 
                console.log(error);
            }
        },

        async delete_row(id) { 
            let loader = this.$loading.show();
            try {
                await axios
                    .delete(this.api_url + "priority_task_items/" + id, {
                        headers: {
                            "Content-Type": "application/json",
                            Authorization: this.token ? `Bearer ${this.token}` : ""
                        },
                    })
                    .then(({
                        res
                    }) => {
                        if (res.data.success) {
                            this.$toasted.show(res.data.message, {
                                theme: "bubble",
                                duration: 5000,
                                position: "bottom-right",
                            });
                        }

                        loader.hide();
                    });
            } catch (error) {
                loader.hide();
            }
            this.getItems();
        },


    },
    computed: {},
};
</script>
